"""Generate PyQt UI/resource modules from the checked-in Designer sources."""

from pathlib import Path
import argparse
import io
import os
import subprocess
import sys
import tempfile
import xml.etree.ElementTree as ET

from PyQt5 import uic


ROOT = Path(__file__).resolve().parents[1]
GUI = ROOT / "src" / "pumpsolver" / "gui"


def generated_files():
    """Return deterministic generated bytes without modifying the checkout."""
    result = {}
    previous = Path.cwd()
    try:
        os.chdir(ROOT)
        for form in sorted((GUI / "forms").glob("*.ui")):
            output = io.StringIO()
            uic.compileUi(form.relative_to(ROOT).as_posix(), output, from_imports=True)
            # The source collection is called assets.qrc; its single compiled
            # module has the more descriptive package name resources_rc.
            source = output.getvalue().replace("from . import assets_rc", "from . import resources_rc")
            result[GUI / "generated" / f"ui_{form.stem}.py"] = source.encode("utf-8")
        resource_source = GUI / "assets" / "assets.qrc"
        for entry in ET.parse(resource_source).findall(".//file"):
            if not (resource_source.parent / entry.text).is_file():
                raise FileNotFoundError(f"Missing Qt resource source: {entry.text}")
        with tempfile.TemporaryDirectory(prefix="pumpsolver-resources-") as temporary:
            output = Path(temporary) / "resources_rc.py"
            subprocess.run(
                [sys.executable, "-m", "PyQt5.pyrcc_main", "-o", str(output),
                 resource_source.relative_to(ROOT).as_posix()],
                check=True, cwd=ROOT,
            )
            result[GUI / "generated" / "resources_rc.py"] = output.read_bytes().replace(b"\r\n", b"\n")
    finally:
        os.chdir(previous)
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if checked-in generated files are stale")
    args = parser.parse_args()
    stale = []
    for target, content in generated_files().items():
        if args.check:
            if not target.exists() or target.read_bytes().replace(b"\r\n", b"\n") != content:
                stale.append(target.relative_to(ROOT).as_posix())
        else:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(content)
    if stale:
        print("Regenerate UI modules: " + ", ".join(stale), file=sys.stderr)
        return 1
    print("Generated sources are current." if args.check else "Generated UI and resource modules.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
